-- LotPulse: one-shot database setup. GENERATED by scripts/setup-sql.ts from
-- supabase/migrations. Don't edit by hand; add a migration and regenerate.
--
-- Paste the whole file into Supabase → SQL Editor → New query and press Run.
-- Safe to run again: migrations already applied are skipped. It runs as one
-- transaction, so a failure changes nothing.

begin;

-- Migration history, shared with the Supabase CLI and GitHub integration.
create schema if not exists supabase_migrations;
create table if not exists supabase_migrations.schema_migrations (
  version text primary key,
  statements text[],
  name text
);

-- Databases set up by hand before this script existed: record what's there.
do $baseline$
begin
  if to_regclass('public.reports') is not null then
    insert into supabase_migrations.schema_migrations (version, name) values
      ('20261008000000', 'live_sightings'),
      ('20261009000000', 'launch_hardening'),
      ('20261011000000', 'reports')
    on conflict (version) do nothing;
  elsif to_regclass('public.sightings') is not null then
    insert into supabase_migrations.schema_migrations (version, name)
    values ('20261008000000', 'live_sightings')
    on conflict (version) do nothing;
    if exists (
      select 1 from pg_policies
      where schemaname = 'public' and tablename = 'sightings'
        and policyname = 'Recent sightings are public'
    ) then
      insert into supabase_migrations.schema_migrations (version, name)
      values ('20261009000000', 'launch_hardening')
      on conflict (version) do nothing;
    end if;
  end if;
end
$baseline$;

-- 20261008000000_live_sightings.sql -------------------------------------------
do $step$
begin
  if not exists (
    select 1 from supabase_migrations.schema_migrations where version = '20261008000000'
  ) then
    execute $lotpulse_migration$
-- LotPulse: shared, live enforcement sightings.
--
-- Students sign in anonymously (Supabase anonymous auth), pick a public scout
-- name, and report sightings per lot. Everyone can read sightings; the guards
-- below are enforced by the database, not the browser.

-- Scout names -----------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  username text not null,
  created_at timestamptz not null default now(),
  constraint profiles_username_format check (username ~ '^[A-Za-z0-9_]{3,20}$')
);

create unique index profiles_username_unique on public.profiles (lower(username));

-- Sightings -------------------------------------------------------------------
create table public.sightings (
  id uuid primary key default gen_random_uuid(),
  lot_id text not null,
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  constraint sightings_lot_id_known check (lot_id in ('P9', 'P4', 'P8', 'P11', 'CCT', 'IC'))
);

create index sightings_created_at_idx on public.sightings (created_at desc);
create index sightings_user_recent_idx on public.sightings (user_id, created_at desc);

-- Row level security ----------------------------------------------------------
alter table public.profiles enable row level security;
alter table public.sightings enable row level security;

create policy "Scout names are public"
  on public.profiles for select
  to anon, authenticated
  using (true);

create policy "Scouts create their own profile"
  on public.profiles for insert
  to authenticated
  with check (id = (select auth.uid()));

create policy "Sightings are public"
  on public.sightings for select
  to anon, authenticated
  using (true);

create policy "Scouts post as themselves"
  on public.sightings for insert
  to authenticated
  with check (user_id = (select auth.uid()));

create policy "Scouts can undo a fresh sighting"
  on public.sightings for delete
  to authenticated
  using (user_id = (select auth.uid()) and created_at > now() - interval '2 minutes');

grant select on public.profiles, public.sightings to anon, authenticated;
grant insert on public.profiles to authenticated;
grant insert, delete on public.sightings to authenticated;

-- Server-side guards ----------------------------------------------------------
-- Timestamps come from the server, and each scout gets a per-lot cooldown and
-- an hourly cap. The advisory lock stops parallel requests slipping past.
create function public.guard_sighting()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.user_id := coalesce(auth.uid(), new.user_id);
  new.created_at := now();

  perform pg_advisory_xact_lock(hashtextextended(new.user_id::text, 0));

  if exists (
    select 1
    from public.sightings s
    where s.user_id = new.user_id
      and s.lot_id = new.lot_id
      and s.created_at > now() - interval '15 minutes'
  ) then
    raise exception 'cooldown: you reported this lot in the last 15 minutes';
  end if;

  if (
    select count(*)
    from public.sightings s
    where s.user_id = new.user_id
      and s.created_at > now() - interval '1 hour'
  ) >= 6 then
    raise exception 'rate_limit: too many sightings in the last hour';
  end if;

  return new;
end;
$$;

create trigger guard_sighting
  before insert on public.sightings
  for each row execute function public.guard_sighting();

-- Weekly leaderboard (weeks start Monday, Toronto time) -----------------------
create view public.weekly_leaderboard
with (security_invoker = true)
as
select
  p.id as user_id,
  p.username,
  count(*)::int as sightings,
  count(*)::int * 25 as points
from public.sightings s
join public.profiles p on p.id = s.user_id
where s.created_at >= (date_trunc('week', now() at time zone 'America/Toronto') at time zone 'America/Toronto')
group by p.id, p.username
order by points desc, p.username;

grant select on public.weekly_leaderboard to anon, authenticated;

-- Live updates ----------------------------------------------------------------
alter publication supabase_realtime add table public.sightings;
$lotpulse_migration$;
    insert into supabase_migrations.schema_migrations (version, name)
    values ('20261008000000', 'live_sightings');
  end if;
end
$step$;

-- 20261009000000_launch_hardening.sql -----------------------------------------
do $step$
begin
  if not exists (
    select 1 from supabase_migrations.schema_migrations where version = '20261009000000'
  ) then
    execute $lotpulse_migration$
-- LotPulse: privacy and abuse hardening before the public launch.

-- Sighting history ------------------------------------------------------------
-- A sighting is the scout name, a lot and a time. Kept readable forever, that
-- adds up to a timeline of when each named scout is on campus. Everyone now
-- sees only the last 24 hours (all the app's feed uses); scouts still see
-- their own reports for their weekly stats.
drop policy "Sightings are public" on public.sightings;

create policy "Recent sightings are public"
  on public.sightings for select
  to anon, authenticated
  using (created_at > now() - interval '24 hours' or user_id = (select auth.uid()));

-- The weekly leaderboard needs the whole week, so it can't read through the
-- 24-hour policy. A security definer function returns only the totals.
drop view public.weekly_leaderboard;

create function public.weekly_leaderboard()
returns table (user_id uuid, username text, sightings int, points int)
language sql
stable
security definer
set search_path = ''
as $$
  select
    p.id,
    p.username,
    count(*)::int,
    count(*)::int * 25
  from public.sightings s
  join public.profiles p on p.id = s.user_id
  where s.created_at >= (date_trunc('week', now() at time zone 'America/Toronto') at time zone 'America/Toronto')
  group by p.id, p.username
  order by 4 desc, p.username;
$$;

revoke execute on function public.weekly_leaderboard() from public;
grant execute on function public.weekly_leaderboard() to anon, authenticated;

-- Scout names -------------------------------------------------------------------
-- Names are public, so block ones that pose as the app, the university or
-- parking staff, plus "You", which the leaderboard uses for the viewer.
-- NOT VALID: applies to new names without failing on any existing ones.
alter table public.profiles
  add constraint profiles_username_reserved check (
    lower(username) !~ '^(you|me|admin|administrator|mod|moderator|staff|support|system|official|utm|uoft|lotpulse.*|.*parking_?(services|enforcement|officer).*|.*campus_?(police|safety|security).*)$'
  ) not valid;
$lotpulse_migration$;
    insert into supabase_migrations.schema_migrations (version, name)
    values ('20261009000000', 'launch_hardening');
  end if;
end
$step$;

-- 20261011000000_reports.sql --------------------------------------------------
do $step$
begin
  if not exists (
    select 1 from supabase_migrations.schema_migrations where version = '20261011000000'
  ) then
    execute $lotpulse_migration$
-- LotPulse: sightings become "reports".
--
-- A report is just a lot, a server timestamp and the anonymous reporter. The
-- table is renamed (existing rows and the realtime publication carry over),
-- the client loses the ability to delete, and the per-lot cooldown drops to
-- 5 minutes.

-- Table and columns -----------------------------------------------------------
alter table public.sightings rename to reports;
alter table public.reports rename column user_id to reporter_id;
alter table public.reports rename constraint sightings_pkey to reports_pkey;
alter table public.reports rename constraint sightings_lot_id_known to reports_lot_id_known;
alter index public.sightings_created_at_idx rename to reports_created_at_idx;
alter index public.sightings_user_recent_idx rename to reports_reporter_recent_idx;
create index reports_lot_recent_idx on public.reports (lot_id, created_at desc);

-- If a scout's profile is deleted, their reports stay as anonymous lot history.
alter table public.reports alter column reporter_id drop not null;
alter table public.reports drop constraint sightings_user_id_fkey;
alter table public.reports
  add constraint reports_reporter_id_fkey
  foreign key (reporter_id) references public.profiles (id) on delete set null;

-- Row level security ----------------------------------------------------------
-- Anyone can read the last 24 hours (and their own older reports), a signed-in
-- scout can only insert as themselves, and nobody can update or delete.
drop policy "Recent sightings are public" on public.reports;
drop policy "Scouts post as themselves" on public.reports;
drop policy "Scouts can undo a fresh sighting" on public.reports;

create policy "Recent reports are public"
  on public.reports for select
  to anon, authenticated
  using (created_at > now() - interval '24 hours' or reporter_id = (select auth.uid()));

create policy "Scouts report as themselves"
  on public.reports for insert
  to authenticated
  with check (reporter_id = (select auth.uid()));

revoke all on public.reports from anon, authenticated;
grant select on public.reports to anon, authenticated;
grant insert (lot_id) on public.reports to authenticated;

-- Server-side guards ----------------------------------------------------------
-- Server timestamps, the reporter is always the caller, one report per scout
-- per lot every 5 minutes and at most 6 an hour. The advisory lock stops
-- parallel requests slipping past.
drop trigger guard_sighting on public.reports;
drop function public.guard_sighting();

create function public.guard_report()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.reporter_id := coalesce(auth.uid(), new.reporter_id);
  new.created_at := now();

  perform pg_advisory_xact_lock(hashtextextended(new.reporter_id::text, 0));

  if exists (
    select 1
    from public.reports r
    where r.reporter_id = new.reporter_id
      and r.lot_id = new.lot_id
      and r.created_at > now() - interval '5 minutes'
  ) then
    raise exception 'cooldown: you reported this lot in the last 5 minutes';
  end if;

  if (
    select count(*)
    from public.reports r
    where r.reporter_id = new.reporter_id
      and r.created_at > now() - interval '1 hour'
  ) >= 6 then
    raise exception 'rate_limit: too many reports in the last hour';
  end if;

  return new;
end;
$$;

create trigger guard_report
  before insert on public.reports
  for each row execute function public.guard_report();

-- Weekly clout: 25 points per report since Monday, Toronto time ---------------
create or replace function public.weekly_leaderboard()
returns table (user_id uuid, username text, sightings int, points int)
language sql
stable
security definer
set search_path = ''
as $$
  select
    p.id,
    p.username,
    count(*)::int,
    count(*)::int * 25
  from public.reports r
  join public.profiles p on p.id = r.reporter_id
  where r.created_at >= (date_trunc('week', now() at time zone 'America/Toronto') at time zone 'America/Toronto')
  group by p.id, p.username
  order by 4 desc, p.username;
$$;
$lotpulse_migration$;
    insert into supabase_migrations.schema_migrations (version, name)
    values ('20261011000000', 'reports');
  end if;
end
$step$;

-- 20261012000000_delete_my_data.sql -------------------------------------------
do $step$
begin
  if not exists (
    select 1 from supabase_migrations.schema_migrations where version = '20261012000000'
  ) then
    execute $lotpulse_migration$
-- LotPulse: scouts delete their own data from the app.
--
-- A scout is an anonymous sign-in that only their browser holds, so the
-- request itself proves who they are; no email or support inbox needed.
-- delete_my_data() removes the caller's reports and their account (the
-- profile goes with it via on delete cascade). It only ever touches
-- auth.uid(), so nobody can delete someone else.

create function public.delete_my_data()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'not_signed_in: nothing to delete';
  end if;
  delete from public.reports where reporter_id = me;
  delete from auth.users where id = me;
end;
$$;

revoke all on function public.delete_my_data() from public, anon;
grant execute on function public.delete_my_data() to authenticated;
$lotpulse_migration$;
    insert into supabase_migrations.schema_migrations (version, name)
    values ('20261012000000', 'delete_my_data');
  end if;
end
$step$;

-- Live updates: make sure every new report is broadcast over Realtime.
do $realtime$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
    and not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'reports'
    )
  then
    alter publication supabase_realtime add table public.reports;
  end if;
end
$realtime$;

-- Let the API see the new tables and functions straight away.
notify pgrst, 'reload schema';

commit;

-- Result: every migration listed, and reports_in_realtime = true.
select
  (select string_agg(version, ', ' order by version) from supabase_migrations.schema_migrations)
    as applied_migrations,
  exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'reports'
  ) as reports_in_realtime;
